origin.example:
x <- github_remote("igraph=igraph/rigraph@v1.0.0", auth_token = NULL)
cat(paste0("github_remote(\"igraph=igraph/rigraph@v1.0.0\", auth_token = NULL) returns package ", x$package, ", repo ", x$repo, ", ref ", x$ref, ".\n"))
pull <- tryCatch(github_remote("r-lib/remotes#7", auth_token = NULL), error = function(e) e)
if (inherits(pull, "error")) {
  cat("github_remote(\"r-lib/remotes#7\", auth_token = NULL) stops with:\n")
  cat(conditionMessage(pull), "\n", sep = "")
} else {
  cat(paste0("github_remote(\"r-lib/remotes#7\", auth_token = NULL) returns username ", pull$username, ", repo ", pull$repo, ", ref ", pull$ref, ".\n"))
}
